package com.badrulamin.University_Management.controller;  import com.badrulamin.University_Management.entity.ApplicationReview; import com.badrulamin.University_Management.service.ApplicationReviewService; import org.springframework.data.domain.Page; import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Sort; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;  import java.util.Map;  @RestController @RequestMapping("/api/application-reviews") @CrossOrigin(origins = "*", maxAge = 3600) public class ApplicationReviewController {      private final ApplicationReviewService applicationReviewService;      public ApplicationReviewController(ApplicationReviewService applicationReviewService) {         this.applicationReviewService = applicationReviewService;     }      @GetMapping     @PreAuthorize("hasAuthority('ADMISSION_MANAGE') or hasAuthority('ADMISSION_VIEW')")     public ResponseEntity<?> findAll(             @RequestParam(defaultValue = "0") int page,             @RequestParam(defaultValue = "20") int size,             @RequestParam(defaultValue = "id") String sort,             @RequestParam(defaultValue = "asc") String direction) {         Sort.Direction sortDirection = "desc".equalsIgnoreCase(direction) ? Sort.Direction.DESC : Sort.Direction.ASC;         Page<ApplicationReview> reviews = applicationReviewService.findAll(PageRequest.of(page, size, Sort.by(sortDirection, sort)));         return ResponseEntity.ok(Map.of(                 "content", reviews.getContent(),                 "totalElements", reviews.getTotalElements(),                 "totalPages", reviews.getTotalPages(),                 "currentPage", reviews.getNumber()         ));     }      @GetMapping("/{id}")     @PreAuthorize("hasAuthority('ADMISSION_MANAGE') or hasAuthority('ADMISSION_VIEW')")     public ResponseEntity<ApplicationReview> findById(@PathVariable Long id) {         return ResponseEntity.ok(applicationReviewService.findById(id));     }      @PostMapping     @PreAuthorize("hasAuthority('ADMISSION_MANAGE') or hasAuthority('ADMISSION_CREATE')")     public ResponseEntity<ApplicationReview> create(@RequestBody ApplicationReview review) {         return ResponseEntity.ok(applicationReviewService.create(review));     }      @PutMapping("/{id}")     @PreAuthorize("hasAuthority('ADMISSION_MANAGE') or hasAuthority('ADMISSION_EDIT')")     public ResponseEntity<ApplicationReview> update(@PathVariable Long id, @RequestBody ApplicationReview review) {         return ResponseEntity.ok(applicationReviewService.update(id, review));     }      @DeleteMapping("/{id}")     @PreAuthorize("hasAuthority('ADMISSION_MANAGE') or hasAuthority('ADMISSION_DELETE')")     public ResponseEntity<Void> delete(@PathVariable Long id) {         applicationReviewService.delete(id);         return ResponseEntity.ok().build();     }      @GetMapping("/stats")     @PreAuthorize("hasAuthority('ADMISSION_MANAGE') or hasAuthority('ADMISSION_VIEW')")     public ResponseEntity<?> getStats() {         return ResponseEntity.ok(Map.of(                 "total", applicationReviewService.countByStatus("PENDING") + applicationReviewService.countByStatus("APPROVED") + applicationReviewService.countByStatus("REJECTED"),                 "pending", applicationReviewService.countByStatus("PENDING"),                 "approved", applicationReviewService.countByStatus("APPROVED"),                 "rejected", applicationReviewService.countByStatus("REJECTED")         ));     } }